import logging
from pathlib import Path
from typing import Unpack

import reflex as rx
from reflex.plugins.base import CommonContext
from reflex_base import constants


class FrontendRuntimePlugin(rx.plugins.Plugin):
    """Emit installed static templates in the same lifecycle as compiled pages."""

    def get_static_assets(
        self, **context: Unpack[CommonContext]
    ) -> list[tuple[Path, str]]:
        template_dir = constants.Templates.Dirs.WEB_TEMPLATE
        # These files are generated by the compiler, including plugin overrides.
        generated = {
            Path("react-router.config.js"),
            Path("postcss.config.js"),
            Path("app/entry.client.js"),
        }
        assets: list[tuple[Path, str]] = []
        try:
            for source in sorted(template_dir.rglob("*")):
                relative = source.relative_to(template_dir)
                if (
                    source.is_file()
                    and not any(part.startswith(".") for part in relative.parts)
                    and relative not in generated
                ):
                    assets.append(
                        (relative, source.read_text(encoding="utf-8"))
                    )
        except OSError as e:
            logging.exception(f"Error: {e}")
            raise
        return assets


config = rx.Config(
    app_name="UniFlow_",
    default_color_mode="light",
    plugins=[
        FrontendRuntimePlugin(),
        rx.plugins.SitemapPlugin(),
        rx.plugins.TailwindV4Plugin(),
        rx.plugins.RadixThemesPlugin(),
    ],
)
